import bcrypt from 'bcrypt';

const JWT_SECRET = process.env.JWT_SECRET || 'secret123';

const app = express();
app.use(express.json());

// JWT verifyToken middleware
function verifyToken(req: any, res: express.Response, next: express.NextFunction) {
    // Exclude /health and POST /users
    if (
        req.path === '/health' ||
        (req.path === '/users' && req.method === 'POST') ||
        (req.path === '/login' && req.method === 'POST')
    ) {
        return next();
    }
    const authHeader = req.headers['authorization'] || req.headers['Authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ error: 'No token provided' });
    }
    const token = authHeader.slice(7); // after 'Bearer '
    jwt.verify(token, JWT_SECRET, (err, decoded) => {
        if (err) return res.status(401).json({ error: 'Invalid token' });
        req.user = decoded;
        next();
    });
}

app.use(verifyToken);

