// Helper to build SQL WHERE clause and params
function buildWhereClause(filters: { [key: string]: any }): { clause: string, params: any[] } {
    const clauses: string[] = [];
    const params: any[] = [];

    // Users
    if (filters.__users_search) {
        clauses.push('(name LIKE ? OR email LIKE ?)');
        params.push(`%${filters.__users_search}%`, `%${filters.__users_search}%`);
    }

    // Orders
    if (filters.status) {
        clauses.push('status = ?');
        params.push(filters.status);
    }
    if (filters.userId) {
        clauses.push('userId = ?');
        params.push(filters.userId);
    }

    // Products
    if (filters.__products_search) {
        clauses.push('(name LIKE ? OR description LIKE ?)');
        params.push(`%${filters.__products_search}%`, `%${filters.__products_search}%`);
    }
    if (filters.minPrice !== undefined) {
        clauses.push('price >= ?');
        params.push(filters.minPrice);
    }
    if (filters.maxPrice !== undefined) {
        clauses.push('price <= ?');
        params.push(filters.maxPrice);
    }

    return {
        clause: clauses.length ? 'WHERE ' + clauses.join(' AND ') : '',
        params,
    };
}

