// CacheStore class
type CacheValue = {
    data: any;
    expires: number;
};
class CacheStore {
    private store: Map<string, CacheValue> = new Map();

    get(key: string): any | undefined {
        const entry = this.store.get(key);
        if (!entry) return undefined;
        if (Date.now() > entry.expires) {
            this.store.delete(key);
            return undefined;
        }
        return entry.data;
    }

    set(key: string, data: any, ttl: number): void {
        this.store.set(key, { data, expires: Date.now() + ttl * 1000 });
    }

    invalidate(pattern: string | RegExp): void {
        for (const key of this.store.keys()) {
            if (typeof pattern === 'string') {
                if (key.startsWith(pattern)) {
                    this.store.delete(key);
                }
            } else {
                if (pattern.test(key)) {
                    this.store.delete(key);
                }
            }
        }
    }

    cleanup(): void {
        const now = Date.now();
        for (const [key, entry] of this.store.entries()) {
            if (now > entry.expires) {
                this.store.delete(key);
            }
        }
    }
}
const cache = new CacheStore();

// Cleanup expired cache entries every 60s
setInterval(() => cache.cleanup(), 60000);

// Helper: generate cache key based on req
function cacheKey(req: express.Request): string {
    return req.originalUrl;
}

// Helper: cache middleware
function cacheMiddleware(ttl: number) {
    return (req: express.Request, res: express.Response, next: express.NextFunction) => {
        const key = cacheKey(req);
        const cached = cache.get(key);
        if (cached !== undefined) {
            res.set('Cache-Control', `public, max-age=${ttl}`);
            return res.json(cached);
        }
        // Monkey patch res.json to store the response in cache
        const originalJson = res.json.bind(res);
        res.json = (body: any) => {
            cache.set(key, body, ttl);
            res.set('Cache-Control', `public, max-age=${ttl}`);
            return originalJson(body);
        };
        next();
    };
}

