// --- In-flight request counter middleware ---
let inFlightRequests = 0;
let isShuttingDown = false;

app.use((req, res, next) => {
    if (isShuttingDown) {
        res.setHeader('Connection', 'close');
        return res.status(503).json({ error: 'Server is shutting down' });
    }
    inFlightRequests++;
    res.on('finish', () => {
        inFlightRequests--;
    });
    next();
});

