// apiVersion middleware
function apiVersion(req: Request, res: Response, next: NextFunction) {
    let version = 'v1';
    const acceptVersion = req.headers['accept-version'];
    if (typeof acceptVersion === 'string' && /^v\d+$/.test(acceptVersion)) {
        version = acceptVersion;
    }
    // Check URL prefix for /v1/ or /v2/
    const match = req.path.match(/^\/(v\d+)\b/);
    if (match) {
        version = match[1];
    }
    // Attach the version to the request object for later use
    (req as any).apiVersion = version;
    if (version === 'v1') {
        res.setHeader('X-API-Deprecation-Notice', 'API version v1 is deprecated and will be removed in future versions.');
    }
    next();
}

