const COMPRESS_THRESHOLD = 1024; // 1KB

const compressedContentTypes = [
    'image/',
    'audio/',
    'video/',
    'application/zip',
    'application/gzip',
    'application/x-gzip',
    'application/pdf',
    'application/vnd.ms-fontobject',
    'application/font-woff',
    'application/font-woff2',
    'application/x-rar-compressed',
    'application/x-tar',
    'application/x-7z-compressed'
];

function isAlreadyCompressed(contentType?: string) {
    if (!contentType) return false;
    contentType = contentType.toLowerCase();
    return compressedContentTypes.some(type =>
        type.endsWith('/') ? contentType.startsWith(type) : contentType.startsWith(type)
    );
}

function selectEncoding(acceptEncoding: string | undefined): 'gzip' | 'deflate' | null {
    if (!acceptEncoding) return null;
    acceptEncoding = acceptEncoding.toLowerCase();
    if (acceptEncoding.includes('gzip')) return 'gzip';
    if (acceptEncoding.includes('deflate')) return 'deflate';
    return null;
}

app.use((req: Request, res: Response, next: NextFunction) => {
    const acceptEncoding = req.headers['accept-encoding'];
    const encoding = selectEncoding(typeof acceptEncoding === 'string' ? acceptEncoding : Array.isArray(acceptEncoding) ? acceptEncoding.join(',') : undefined);

    if (!encoding) {
        return next();
    }

    let _write = res.write.bind(res);
    let _end = res.end.bind(res);
    let _writeHead = res.writeHead ? res.writeHead.bind(res) : undefined;
    let chunks: Buffer[] = [];
    let headersSent = false;

    function sendCompressed(buffer: Buffer) {
        if (encoding === 'gzip') {
            zlib.gzip(buffer, (err, compressed) => {
                if (err) {
                    res.removeHeader('Content-Encoding');
                    res.removeHeader('Content-Length');
                    _write(buffer);
                    _end();
                    return;
                }
                res.setHeader('Content-Encoding', 'gzip');
                res.setHeader('Content-Length', compressed.length);
                _write(compressed);
                _end();
            });
        } else if (encoding === 'deflate') {
            zlib.deflate(buffer, (err, compressed) => {
                if (err) {
                    res.removeHeader('Content-Encoding');
                    res.removeHeader('Content-Length');
                    _write(buffer);
                    _end();
                    return;
                }
                res.setHeader('Content-Encoding', 'deflate');
                res.setHeader('Content-Length', compressed.length);
                _write(compressed);
                _end();
            });
        }
    }

    res.write = function(chunk: any, ...args: any[]): boolean {
        if (headersSent) return false; // ignore writes after end
        if (typeof chunk === 'string') {
            chunk = Buffer.from(chunk, args[0] || 'utf8');
        }
        chunks.push(chunk);
        return true;
    };

    res.end = function(chunk?: any, ...args: any[]): Response {
        if (headersSent) return res;
        headersSent = true;

        if (chunk) {
            if (typeof chunk === 'string') {
                chunk = Buffer.from(chunk, args[0] || 'utf8');
            }
            chunks.push(chunk);
        }
        const body = Buffer.concat(chunks);

        const contentType = res.getHeader('Content-Type') as string | undefined;
        if (isAlreadyCompressed(contentType) || body.length < COMPRESS_THRESHOLD) {
            // don't compress
            res.removeHeader('Content-Encoding');
            res.setHeader('Content-Length', body.length);
            _write(body);
            _end();
            return res;
        }

        // compress!
        sendCompressed(body);
        return res;
    };

    // If .writeHead is used, update Content-Encoding accordingly
    if (_writeHead) {
        res.writeHead = function(...args: any[]) {
            if (res.getHeader('Content-Encoding')) {
                // already set in compression
            }
            // delay sending headers until after compression
            return res;
        } as any;
    }

    next();
});
// --- End Compression Middleware ---

