import express from 'express';
import { db } from './db';
import crypto from 'crypto';

const app = express();
app.use(express.json());

// --- API Key Store (in-memory) ---
type ApiKeyMeta = {
    name: string;
    created_at: string;
    permissions: string[];
    owner?: string;
};
const apiKeys = new Map<string, ApiKeyMeta>();

// --- Dummy JWT Middleware Placeholder ---
function authenticateJWT(req: any, res: any, next: any) {
    // This is a placeholder. In real apps, it would verify JWT and attach req.user
    if (req.headers.authorization && req.headers.authorization.startsWith('Bearer ')) {
        // Example user, in a real app parse JWT
        req.user = { id: 1, role: 'admin' }; // or 'user'
        return next();
    }
    return next();
}

// --- API Key/JWT Auth Middleware ---
function apiAuth(req: any, res: any, next: any) {
    // Check API Key auth
    const apiKey = req.headers['x-api-key'];
    if (apiKey && typeof apiKey === 'string' && apiKeys.has(apiKey)) {
        const meta = apiKeys.get(apiKey)!;
        req.apiKey = { key: apiKey, ...meta };
        // For admin check, also set req.user with role if permission includes "admin"
        if (meta.permissions.includes('admin')) {
            req.user = { id: null, role: 'admin', apiKey: true };
        } else {
            req.user = { id: null, role: 'user', apiKey: true };
        }
        return next();
    }
    // Try JWT authentication if API Key missing or invalid
    authenticateJWT(req, res, () => {
        if (req.user) {
            return next();
        }
        res.status(401).json({ error: 'Unauthorized' });
    });
}

// --- Admin Only Middleware ---
function requireAdmin(req: any, res: any, next: any) {
    // Admin via JWT or via API Key with admin permission
    if (req.user && req.user.role === 'admin') return next();
    return res.status(403).json({ error: 'Admin only' });
}

// --- API Key Management Routes ---
// List all API keys (admin only)
app.get('/api-keys', apiAuth, requireAdmin, (req, res) => {
    const list = Array.from(apiKeys.entries()).map(([key, meta]) => ({
        key,
        ...meta
    }));
    res.json(list);
});

// Create new API key (admin only)
app.post('/api-keys', apiAuth, requireAdmin, (req, res) => {
    const { name, permissions = [] } = req.body;
    if (!name || !Array.isArray(permissions)) {
        return res.status(400).json({ error: 'Missing name or permissions' });
    }
    // Generate a secure random API key
    const key = crypto.randomBytes(32).toString('hex');
    const created_at = new Date().toISOString();
    apiKeys.set(key, { name, created_at, permissions });
    res.status(201).json({ key, name, created_at, permissions });
});

