import express from 'express';
import { db } from './db';
import axios from 'axios';

const app = express();
app.use(express.json());

type WebhookEvent = 'user.created' | 'order.created' | 'product.created';

interface WebhookRegistration {
    url: string;
    events: WebhookEvent[];
}

const registeredWebhooks: WebhookRegistration[] = [];

// Health check
app.get('/health', (req, res) => {
    res.json({ status: 'ok', uptime: process.uptime() });
});

// Webhook registration
app.post('/webhooks', (req, res) => {
    const { url, events } = req.body;
    if (!url || !Array.isArray(events) || events.length === 0) {
        return res.status(400).json({ error: 'url and events array are required' });
    }
    const validEvents: WebhookEvent[] = ['user.created', 'order.created', 'product.created'];
    for (const event of events) {
        if (!validEvents.includes(event)) {
            return res.status(400).json({ error: `Invalid event type: ${event}` });
        }
    }
    // Prevent duplicate registration
    const exists = registeredWebhooks.find(w => w.url === url && JSON.stringify(w.events.sort()) === JSON.stringify(events.slice().sort()));
    if (!exists) {
        registeredWebhooks.push({ url, events });
    }
    res.status(201).json({ success: true });
});

app.get('/webhooks', (req, res) => {
    res.json(registeredWebhooks);
});

async function triggerWebhook(event: WebhookEvent, payload: any) {
    const targets = registeredWebhooks.filter(w => w.events.includes(event));
    await Promise.all(targets.map(async (wh) => {
        try {
            await axios.post(wh.url, { event, payload }, { timeout: 5000 });
        } catch (err) {
            // Silent fail, or log if needed
            console.error(`Failed to send webhook to ${wh.url}:`, err.message || err);
        }
    }));
}

