// Helper for batch processing
async function processBatch<T>(
    items: T[],
    handler: (item: T, idx: number) => Promise<any>
): Promise<{ succeeded: number, failed: number, errors: Array<{ index: number, error: any }> }> {
    let succeeded = 0;
    let failed = 0;
    const errors: Array<{ index: number, error: any }> = [];

    await Promise.all(items.map(async (item, idx) => {
        try {
            await handler(item, idx);
            succeeded++;
        } catch (error) {
            failed++;
            errors.push({ index: idx, error: error instanceof Error ? error.message : error });
        }
    }));

    return { succeeded, failed, errors };
}

