app.post('/users/batch', async (req, res) => {
    const users: Array<{ name: string, email: string }> = Array.isArray(req.body) ? req.body : [];
    if (!Array.isArray(users)) return res.status(400).json({ error: 'Body must be an array' });

    const batchResult = await processBatch(users, async (user) => {
        if (!user.name || !user.email) throw new Error('Missing name or email');
        await db.insert('users', user);
    });

    res.status(207).json(batchResult);
});

app.delete('/users/batch', async (req, res) => {
    const ids: string[] = Array.isArray(req.body) ? req.body : [];
    if (!Array.isArray(ids)) return res.status(400).json({ error: 'Body must be an array of IDs' });

    const batchResult = await processBatch(ids, async (id) => {
        const deleted = await db.delete('users', id);
        if (!deleted) throw new Error('User not found');
    });

    res.status(207).json(batchResult);
});

