// Helper to select specific fields from an object or array of objects
function selectFields<T extends Record<string, any>>(data: T | T[], fields?: string[]): any {
    if (!fields || fields.length === 0) return data;
    if (Array.isArray(data)) {
        return data.map(obj => {
            const filtered: Record<string, any> = {};
            for (const key of fields) {
                if (key in obj) filtered[key] = obj[key];
            }
            return filtered;
        });
    } else {
        const filtered: Record<string, any> = {};
        for (const key of fields) {
            if (key in data) filtered[key] = data[key];
        }
        return filtered;
    }
}

// Helper to get fields from query param
function getFieldSelection(req: express.Request): string[] | undefined {
    const fieldsParam = req.query.fields;
    if (!fieldsParam) return undefined;
    if (typeof fieldsParam === 'string') {
        return fieldsParam.split(',').map(f => f.trim()).filter(Boolean);
    }
    // If fields appears multiple times (?fields=name&fields=email) - flatten all
    if (Array.isArray(fieldsParam)) {
        return fieldsParam.flatMap(f => f.split(',').map(x => x.trim())).filter(Boolean);
    }
    return undefined;
}

