import crypto from 'crypto';

const app = express();
app.use(express.json());

// Helper to generate ETag from response content
function generateETag(body: any): string {
    const content = typeof body === 'string' ? body : JSON.stringify(body);
    return '"' + crypto.createHash('md5').update(content).digest('hex') + '"';
}

// Helper to get Last-Modified from array of rows or object
function getLastModified(entity: any): string | undefined {
    // Try to find the most recent updated_at/modified/created field
    let dates: Date[] = [];
    if (Array.isArray(entity)) {
        entity.forEach(row => {
            if (row.updated_at) dates.push(new Date(row.updated_at));
            else if (row.modified) dates.push(new Date(row.modified));
            else if (row.created_at) dates.push(new Date(row.created_at));
            else if (row.created) dates.push(new Date(row.created));
        });
    } else if (entity && typeof entity === 'object') {
        if (entity.updated_at) dates.push(new Date(entity.updated_at));
        else if (entity.modified) dates.push(new Date(entity.modified));
        else if (entity.created_at) dates.push(new Date(entity.created_at));
        else if (entity.created) dates.push(new Date(entity.created));
    }
    if (dates.length > 0) {
        const maxDate = new Date(Math.max(...dates.map(d => d.getTime())));
        return maxDate.toUTCString();
    }
    return undefined;
}

// ETag & Last-Modified middleware for GET requests
function withETag(handler: (req: express.Request, res: express.Response, next?: express.NextFunction) => Promise<any>) {
    return async (req: express.Request, res: express.Response, next?: express.NextFunction) => {
        // Only apply to GET
        if (req.method !== 'GET') {
            return handler(req, res, next);
        }

        let sent = false;
        // Monkey-patch res.json and res.send to intercept body
        const originalJson = res.json.bind(res);
        const originalSend = res.send.bind(res);

        function sendWithETag(body: any) {
            if (sent) return;
            sent = true;
            const etag = generateETag(body);
            res.set('ETag', etag);

            // Last-Modified header
            const lastModified = getLastModified(body);
            if (lastModified) {
                res.set('Last-Modified', lastModified);
            }

            // If-None-Match support
            if (req.headers['if-none-match'] === etag) {
                res.status(304).end();
                return;
            }

            if (typeof body === 'object') {
                originalJson(body);
            } else {
                originalSend(body);
            }
        }

        res.json = sendWithETag as any;
        res.send = sendWithETag as any;

        try {
            await handler(req, res, next);
        } catch (e) {
            // Restore originals in case of error
            res.json = originalJson;
            res.send = originalSend;
            throw e;
        }
        // Restore for any non-intercepted cases
        res.json = originalJson;
        res.send = originalSend;
    };
}

