// --- Sanitize Middleware ---
function stripHtmlTags(str: string): string {
    return str.replace(/<\/?[^>]+(>|$)/g, '');
}

function escapeSqlSpecialChars(str: string): string {
    // Escape ' " \ NUL \n \r \x1a
    return str
        .replace(/\\/g, '\\\\')
        .replace(/\'/g, "\\'")
        .replace(/\"/g, '\\"')
        .replace(/\0/g, '\\0')
        .replace(/\n/g, '\\n')
        .replace(/\r/g, '\\r')
        .replace(/\x1a/g, '\\Z');
}

function sanitizeString(str: string): string {
    let sanitized = str;
    sanitized = stripHtmlTags(sanitized);
    sanitized = sanitized.trim();
    sanitized = escapeSqlSpecialChars(sanitized);
    return sanitized;
}

function sanitizeBody(obj: any): any {
    if (typeof obj === 'string') {
        return sanitizeString(obj);
    } else if (Array.isArray(obj)) {
        return obj.map(sanitizeBody);
    } else if (obj && typeof obj === 'object') {
        const sanitizedObj: any = {};
        for (const key of Object.keys(obj)) {
            sanitizedObj[key] = sanitizeBody(obj[key]);
        }
        return sanitizedObj;
    }
    return obj;
}

const sanitizeBodyMiddleware = (req: express.Request, res: express.Response, next: express.NextFunction) => {
    if (req.body) {
        req.body = sanitizeBody(req.body);
    }
    next();
};
// --- End Sanitize Middleware ---

