import express, { Request, Response, NextFunction } from 'express';
import { db } from './db';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(express.json());

// Response envelope helpers
declare global {
    namespace Express {
        interface Response {
            sendSuccess: (data: any, statusCode?: number) => void;
            sendError: (error: any, statusCode?: number) => void;
        }
    }
}

// Middleware to attach requestId to each request
app.use((req: Request, res: Response, next: NextFunction) => {
    (req as any).requestId = uuidv4();
    next();
});

// Attach sendSuccess and sendError helpers
app.use((req: Request, res: Response, next: NextFunction) => {
    res.sendSuccess = (data: any, statusCode: number = 200) => {
        res.status(statusCode).json({
            success: true,
            data,
            error: null,
            timestamp: new Date().toISOString(),
            requestId: (req as any).requestId,
        });
    };
    res.sendError = (error: any, statusCode: number = 500) => {
        let errorObj = typeof error === 'string' ? { message: error } : error;
        res.status(statusCode).json({
            success: false,
            data: null,
            error: errorObj,
            timestamp: new Date().toISOString(),
            requestId: (req as any).requestId,
        });
    };
    next();
});

