import express from 'express';
import { db } from './db';
import fs from 'fs';
import path from 'path';

const app = express();
app.use(express.json());

const packageJsonPath = path.resolve(__dirname, '../package.json');
let appVersion = 'unknown';
try {
    const pkg = JSON.parse(fs.readFileSync(packageJsonPath, 'utf-8'));
    if (pkg && pkg.version) appVersion = pkg.version;
} catch (e) {
    // ignore
}

async function runHealthChecks() {
    const checks: any = {};

    // Database connectivity and response time
    let dbStatus = 'unknown';
    let dbResponseTimeMs = null;
    try {
        const start = process.hrtime.bigint();
        await db.query('SELECT 1');
        const end = process.hrtime.bigint();
        dbStatus = 'ok';
        dbResponseTimeMs = Number(end - start) / 1e6;
    } catch (err) {
        dbStatus = 'error';
    }
    checks.database = {
        status: dbStatus,
        responseTimeMs: dbResponseTimeMs,
    };

    // Memory usage
    const mem = process.memoryUsage();
    checks.memory = {
        rss: mem.rss,
        heapTotal: mem.heapTotal,
        heapUsed: mem.heapUsed,
        external: mem.external,
        arrayBuffers: mem.arrayBuffers,
    };

    // Uptime
    checks.uptime = process.uptime();

    // Version
    checks.version = appVersion;

    return checks;
}

// Health check
app.get('/health', async (req, res) => {
    const checks = await runHealthChecks();
    res.json({
        status: checks.database.status === 'ok' ? 'ok' : 'error',
