import express from 'express';
import { db } from './db';

type CachedResult = {
    statusCode: number;
    body: any;
    headers: Record<string, any>;
    createdAt: number;
};

class IdempotencyStore {
    private store: Map<string, CachedResult>;
    private ttl: number;
    private cleanupInterval: NodeJS.Timeout;

    constructor(ttlMs: number = 24 * 60 * 60 * 1000) {
        this.store = new Map();
        this.ttl = ttlMs;
        this.cleanupInterval = setInterval(this.cleanup.bind(this), 60 * 60 * 1000); // cleanup every hour
    }

    get(key: string): CachedResult | undefined {
        const entry = this.store.get(key);
        if (!entry) return undefined;
        if (Date.now() - entry.createdAt > this.ttl) {
            this.store.delete(key);
            return undefined;
        }
        return entry;
    }

    set(key: string, result: { statusCode: number; body: any; headers: Record<string, any>; }) {
        this.store.set(key, {
            ...result,
            createdAt: Date.now(),
        });
    }

    private cleanup() {
        const now = Date.now();
        for (const [key, entry] of this.store.entries()) {
            if (now - entry.createdAt > this.ttl) {
                this.store.delete(key);
            }
        }
    }

    stopCleanup() {
        clearInterval(this.cleanupInterval);
    }
}

const idempotencyStore = new IdempotencyStore();

