// Idempotency middleware for POST routes
function idempotencyMiddleware(req: express.Request, res: express.Response, next: express.NextFunction) {
    if (req.method !== 'POST') return next();

    const key = req.header('Idempotency-Key');
    if (!key) return next();

    const cached = idempotencyStore.get(key);
    if (cached) {
        for (const [h, v] of Object.entries(cached.headers)) {
            res.setHeader(h, v);
        }
        res.status(cached.statusCode).json(cached.body);
        return;
    }

    // Intercept res.json to cache result
    let bodyData: any;
    const originalJson = res.json.bind(res);
    res.json = (body: any) => {
        bodyData = body;
        return originalJson(body);
    };

    const originalStatus = res.status.bind(res);
    let statusCode = 200;
    res.status = (code: number) => {
        statusCode = code;
        return originalStatus(code);
    };

    // After response is sent, cache the result if Idempotency-Key is present
    res.on('finish', () => {
        // Only cache successful responses (status 2xx or 4xx/5xx? cache all for strict idempotency)
        if (!res.headersSent) return;
        if (bodyData !== undefined) {
            const headers: Record<string, any> = {};
            // Only store headers that are safe to return, or just Content-Type for now
            if (res.getHeader('Content-Type')) {
                headers['Content-Type'] = res.getHeader('Content-Type');
            }
            idempotencyStore.set(key, {
                statusCode,
                body: bodyData,
                headers,
            });
        }
    });

    next();
}
