// Helper for bulk updates
async function processBulkUpdate(
    table: string,
    updates: Array<{ id: string | number; [key: string]: any }>
): Promise<{ updated: number; failures: Array<{ id: string | number; error: string }> }> {
    let updated = 0;
    const failures: Array<{ id: string | number; error: string }> = [];

    for (const u of updates) {
        const { id, ...fields } = u;
        if (!id) {
            failures.push({ id, error: 'Missing id' });
            continue;
        }
        try {
            const result = await db.update(table, id, fields);
            if (result) {
                updated++;
            } else {
                failures.push({ id, error: 'Not found' });
            }
        } catch (err: any) {
            failures.push({ id, error: err.message || 'Unknown error' });
        }
    }
    return { updated, failures };
}

