// Helper functions for content negotiation
function toXml(data: any, rootTag = 'response'): string {
    let xml = `<${rootTag}>`;
    if (Array.isArray(data)) {
        data.forEach(item => {
            xml += objectToXml(item, 'item');
        });
    } else if (typeof data === 'object' && data !== null) {
        xml += objectToXml(data, 'item');
    } else {
        xml += data;
    }
    xml += `</${rootTag}>`;
    return xml;
}

function objectToXml(obj: any, tagName: string): string {
    let xml = `<${tagName}>`;
    for (const key in obj) {
        if (obj.hasOwnProperty(key)) {
            const value = obj[key];
            if (typeof value === 'object' && value !== null) {
                xml += objectToXml(value, key);
            } else {
                xml += `<${key}>${escapeXml(String(value))}</${key}>`;
            }
        }
    }
    xml += `</${tagName}>`;
    return xml;
}

function escapeXml(unsafe: string): string {
    return unsafe.replace(/[<>&'"]/g, function (c) {
        switch (c) {
            case '<': return '&lt;';
            case '>': return '&gt;';
            case '&': return '&amp;';
            case '\'': return '&apos;';
            case '"': return '&quot;';
            default: return c;
        }
    });
}

function toCsv(data: any): string {
    if (!Array.isArray(data)) data = [data];
    if (data.length === 0) return '';
    const keys = Object.keys(flattenObject(data[0]));
    const csvRows = [keys.join(',')];
    for (const row of data) {
        const flat = flattenObject(row);
        const values = keys.map(key => {
            const val = flat[key];
            if (val == null) return '';
            // Escape double quotes in values for CSV
            const strVal = String(val).replace(/"/g, '""');
            if (/[,\"\n]/.test(strVal)) {
                return `"${strVal}"`;
            }
            return strVal;
        });
        csvRows.push(values.join(','));
    }
    return csvRows.join('\n');
}

function flattenObject(ob: any, prefix = '', res = {} as Record<string, any>): Record<string, any> {
    for (const key in ob) {
        if (!ob.hasOwnProperty(key)) continue;
        const value = ob[key];
        if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
            flattenObject(value, prefix ? `${prefix}.${key}` : key, res);
        } else {
            res[prefix ? `${prefix}.${key}` : key] = value;
        }
    }
    return res;
}

function negotiateFormat(req: express.Request, res: express.Response, data: any, rootTag?: string) {
    const accept = req.header('Accept');
    if (accept && accept.includes('text/csv')) {
        res.type('text/csv').send(toCsv(data));
    } else if (accept && (accept.includes('application/xml') || accept.includes('text/xml'))) {
        res.type('application/xml').send(toXml(data, rootTag));
    } else {
        res.json(data);
    }
}

