let concurrentRequests = 0;

const concurrencyTracker = (req: express.Request, res: express.Response, next: express.NextFunction) => {
    concurrentRequests++;
    if (concurrentRequests > 1000) {
        res.set('Retry-After', '10');
        concurrentRequests--;
        return res.status(503).json({ error: 'Server overloaded. Please try again later.' });
    }
    res.on('finish', () => {
        concurrentRequests--;
    });
    next();
};

