// Helper to calculate query complexity
function calculateComplexity(req: express.Request): number {
    // Consider filters as non-pagination and non-sort query parameters
    const filterKeys = Object.keys(req.query).filter(
        (key) => key !== 'sort' && key !== 'order' && key !== 'page' && key !== 'limit' && key !== 'offset'
    );
    const numFilters = filterKeys.length;

    // Support sort as comma-separated list or array or single value
    let sortFields = 0;
    if (req.query.sort) {
        if (Array.isArray(req.query.sort)) {
            sortFields = req.query.sort.length;
        } else if (typeof req.query.sort === 'string') {
            sortFields = req.query.sort.split(',').filter(Boolean).length;
        } else {
            sortFields = 1;
        }
    }

    // Page size (limit), default to 10 if not specified
    let pageSize = 10;
    if (req.query.limit) {
        const parsed = parseInt(Array.isArray(req.query.limit) ? req.query.limit[0] : req.query.limit as string, 10);
        if (!isNaN(parsed)) {
            pageSize = parsed;
        }
    }

    return numFilters + sortFields + pageSize;
}

