// Helper for cascade deletion and update
async function cascadeDelete(entity: 'users' | 'products', id: string) {
    let cascadedDeletions = 0;
    if (entity === 'users') {
        // Delete all orders for user
        const userOrders = await db.query('SELECT id FROM orders WHERE userId = ?', [id]);
        if (userOrders && Array.isArray(userOrders) && userOrders.length > 0) {
            for (const order of userOrders) {
                await db.delete('orders', order.id);
                cascadedDeletions++;
                console.log(`[Cascade] Deleted order ${order.id} for user ${id}`);
            }
        }
    } else if (entity === 'products') {
        // Update orders that reference this product
        const orders = await db.query('SELECT id, items FROM orders');
        if (orders && Array.isArray(orders)) {
            for (const order of orders) {
                let changed = false;
                let items = order.items;
                if (Array.isArray(items)) {
                    // items is array of product ids or objects
                    const filtered = items.filter((item: any) => {
                        if (typeof item === 'string' || typeof item === 'number') {
                            return String(item) !== String(id);
                        } else if (item && item.productId) {
                            return String(item.productId) !== String(id);
                        }
                        return true;
                    });
                    if (filtered.length !== items.length) {
                        changed = true;
                        items = filtered;
                    }
                }
                if (changed) {
                    await db.update('orders', order.id, { items });
                    cascadedDeletions++;
                    console.log(`[Cascade] Updated order ${order.id}: removed product ${id} from items`);
                }
            }
        }
    }
    return cascadedDeletions;
}

