// Helper: Stream results as JSON or CSV
async function streamResults(
    res: express.Response,
    query: string,
    params: any[],
    filename: string,
    format: 'json' | 'csv'
) {
    res.setHeader(
        'Content-Disposition',
        `attachment; filename="${filename}.${format}"`
    );
    res.setHeader('Content-Type', format === 'csv' ? 'text/csv' : 'application/json');

    // Simulated streaming from db.queryStream (if available), else fallback to memory
    if (typeof db.queryStream === 'function') {
        // If db.queryStream exists, use streaming
        const stream = db.queryStream(query, params);
        let isFirst = true;
        if (format === 'json') {
            res.write('[');
            stream.on('data', (row: any) => {
                res.write((isFirst ? '' : ',') + JSON.stringify(row));
                isFirst = false;
            });
            stream.on('end', () => {
                res.write(']');
                res.end();
            });
            stream.on('error', (err: any) => {
                res.status(500).end(JSON.stringify({ error: err.message }));
            });
        } else {
            let headerWritten = false;
            stream.on('data', (row: any) => {
                if (!headerWritten) {
                    res.write(Object.keys(row).join(',') + '\n');
                    headerWritten = true;
                }
                res.write(
                    Object.values(row)
                        .map((val) =>
                            typeof val === 'string' && /[,"\n]/.test(val)
                                ? `"${val.replace(/"/g, '""')}"`
                                : val
                        )
                        .join(',') + '\n'
                );
            });
            stream.on('end', () => res.end());
            stream.on('error', (err: any) => {
                res.status(500).end(`error: ${err.message}`);
            });
        }
    } else {
        // Fallback: load all to memory if streaming not available
        const rows = await db.query(query, params);
        if (format === 'json') {
            res.end(JSON.stringify(rows));
        } else {
            if (rows.length === 0) {
                res.end('');
                return;
            }
            const header = Object.keys(rows[0]).join(',') + '\n';
            const body = rows
                .map((row: any) =>
                    Object.values(row)
                        .map((val) =>
                            typeof val === 'string' && /[,"\n]/.test(val)
                                ? `"${val.replace(/"/g, '""')}"`
                                : val
                        )
                        .join(',')
                )
                .join('\n');
            res.end(header + body + '\n');
        }
    }
}

