import crypto from 'crypto';

class RequestDeduplicator {
    private cache: Map<string, {
        timestamp: number,
        statusCode: number,
        headers: Record<string, any>,
        body: any
    }>;
    private cleanupInterval: NodeJS.Timeout;
    private windowMs: number;

    constructor(windowMs: number = 5000) {
        this.cache = new Map();
        this.windowMs = windowMs;
        this.cleanupInterval = setInterval(() => this.cleanup(), this.windowMs);
    }

    genKey(method: string, path: string, body: any) {
        const bodyStr = typeof body === 'string' ? body : JSON.stringify(body || {});
        const hash = crypto.createHash('sha256').update(bodyStr).digest('hex');
        return `${method}|${path}|${hash}`;
    }

    get(key: string) {
        const entry = this.cache.get(key);
        if (!entry) return null;
        if (Date.now() - entry.timestamp > this.windowMs) {
            this.cache.delete(key);
            return null;
        }
        return entry;
    }

    set(key: string, statusCode: number, headers: Record<string, any>, body: any) {
        this.cache.set(key, {
            timestamp: Date.now(),
            statusCode,
            headers,
            body
        });
    }

    cleanup() {
        const now = Date.now();
        for (const [key, value] of this.cache.entries()) {
            if (now - value.timestamp > this.windowMs) {
                this.cache.delete(key);
            }
        }
    }
}

const deduplicator = new RequestDeduplicator();

const deduplicationMiddleware = (req: express.Request, res: express.Response, next: express.NextFunction) => {
    // Only deduplicate for JSON requests
    if (req.method === 'GET' || req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE') {
        // Use originalUrl so query params are included
        const key = deduplicator.genKey(req.method, req.originalUrl, req.body);

        const cached = deduplicator.get(key);
        if (cached) {
            // Send cached response
            res.status(cached.statusCode);
            for (const [headerKey, headerVal] of Object.entries(cached.headers)) {
                res.setHeader(headerKey, headerVal as string);
            }
            // To avoid double encoding, we send the same way as originally sent
            if (typeof cached.body === 'object') {
                res.json(cached.body);
            } else {
                res.send(cached.body);
            }
            return;
        }

        // Monkey-patch res.json and res.send to cache the response
        const _json = res.json;
        const _send = res.send;

        (res as any).__dedupBody = undefined;
        res.json = function (body: any) {
            (res as any).__dedupBody = body;
            return _json.call(this, body);
        };
        res.send = function (body: any) {
            (res as any).__dedupBody = body;
            return _send.call(this, body);
        };

        res.on('finish', () => {
            // Only cache 2xx/3xx/4xx responses (not 5xx error stacks)
            if (res.statusCode < 600) {
                // Copy headers, but remove some express internals
                const headers: Record<string, any> = {};
                for (const [k, v] of Object.entries(res.getHeaders())) {
                    if (typeof v !== 'undefined') {
                        headers[k] = v;
                    }
                }
                deduplicator.set(key, res.statusCode, headers, (res as any).__dedupBody);
            }
        });
    }
    next();
};

