type CircuitBreakerState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

class CircuitBreaker {
    private failureCount: number = 0;
    private readonly failureThreshold: number;
    private state: CircuitBreakerState = 'CLOSED';
    private openUntil: number = 0;
    private readonly openTime: number; // milliseconds
    private testRequestPending: boolean = false;

    constructor(failureThreshold = 5, openTime = 30000) {
        this.failureThreshold = failureThreshold;
        this.openTime = openTime;
    }

    private now() {
        return Date.now();
    }

    private setOpen() {
        this.state = 'OPEN';
        this.openUntil = this.now() + this.openTime;
        this.testRequestPending = true;
    }

    private setHalfOpen() {
        this.state = 'HALF_OPEN';
    }

    private setClosed() {
        this.state = 'CLOSED';
        this.failureCount = 0;
        this.openUntil = 0;
        this.testRequestPending = false;
    }

    public async exec<T>(fn: () => Promise<T>): Promise<T> {
        if (this.state === 'OPEN') {
            if (this.now() >= this.openUntil) {
                // Move to half-open and allow one test request
                this.setHalfOpen();
            } else {
                throw new CircuitBreakerOpenError();
            }
        }
        if (this.state === 'HALF_OPEN') {
            if (!this.testRequestPending) {
                // Only allow one test request
                throw new CircuitBreakerOpenError();
            }
            this.testRequestPending = false;
        }
        try {
            const result = await fn();
            if (this.state === 'HALF_OPEN') {
                this.setClosed();
            } else if (this.state === 'CLOSED') {
                this.failureCount = 0;
            }
            return result;
        } catch (err) {
            this.failureCount++;
            if (this.state === 'HALF_OPEN' || this.failureCount >= this.failureThreshold) {
                this.setOpen();
            }
            throw err;
        }
    }
}

class CircuitBreakerOpenError extends Error {
    constructor() {
        super('Circuit breaker is open');
        this.name = 'CircuitBreakerOpenError';
    }
}

