import express from 'express';
import { db } from './db';

type RouteKey = string;

interface ThrottleConfig {
    maxConcurrent: number;
    maxQueue: number;
}

interface PendingRequest {
    req: express.Request;
    res: express.Response;
    next: express.NextFunction;
}

class ThrottleManager {
    private routeConfigs: Map<RouteKey, ThrottleConfig>;
    private activeCounts: Map<RouteKey, number>;
    private queues: Map<RouteKey, PendingRequest[]>;

    constructor(routeConfigs: { [key: string]: ThrottleConfig }) {
        this.routeConfigs = new Map(Object.entries(routeConfigs));
        this.activeCounts = new Map();
        this.queues = new Map();
    }

    private getRouteKey(method: string, path: string): RouteKey {
        return `${method.toUpperCase()} ${path}`;
    }

    public middleware = (method: string, path: string) => {
        const routeKey = this.getRouteKey(method, path);
        return (req: express.Request, res: express.Response, next: express.NextFunction) => {
            const config = this.routeConfigs.get(routeKey);
            if (!config) {
                // No config for this route, do nothing
                return next();
            }
            if (!this.activeCounts.has(routeKey)) this.activeCounts.set(routeKey, 0);
            if (!this.queues.has(routeKey)) this.queues.set(routeKey, []);

            const active = this.activeCounts.get(routeKey)!;
            const queue = this.queues.get(routeKey)!;

            // If there is room, process immediately
            if (active < config.maxConcurrent) {
                this.activeCounts.set(routeKey, active + 1);

                // Wrap res.end to detect when response is done
                const onDone = () => {
                    res.removeListener('finish', onDone);
                    res.removeListener('close', onDone);
                    this.activeCounts.set(routeKey, this.activeCounts.get(routeKey)! - 1);
                    this.processNext(routeKey);
                };
                res.on('finish', onDone);
                res.on('close', onDone);

                return next();
            } else {
                // If the queue is too long, reject
                if (queue.length >= config.maxQueue) {
                    return res.status(429).json({ error: 'Too many requests, please try again later.' });
                }
                // Otherwise, queue the request
                queue.push({ req, res, next });

                // Optionally set a timeout here if desired
            }
        };
    };

    private processNext(routeKey: RouteKey) {
        const config = this.routeConfigs.get(routeKey);
        if (!config) return;
        const queue = this.queues.get(routeKey);
        if (!queue || queue.length === 0) return;
        const active = this.activeCounts.get(routeKey)!;

        if (active < config.maxConcurrent) {
            const { req, res, next } = queue.shift()!;
            this.activeCounts.set(routeKey, active + 1);

            const onDone = () => {
                res.removeListener('finish', onDone);
                res.removeListener('close', onDone);
                this.activeCounts.set(routeKey, this.activeCounts.get(routeKey)! - 1);
                this.processNext(routeKey);
            };
            res.on('finish', onDone);
            res.on('close', onDone);

            next();
        }
    }
}

// Configure throttling per endpoint
