// Helper to mask sensitive data recursively
function maskSensitiveData(data: any): any {
    if (Array.isArray(data)) {
        return data.map(item => maskSensitiveData(item));
    } else if (data && typeof data === 'object') {
        const masked: any = {};
        for (const key of Object.keys(data)) {
            // Lowercase key for comparison
            const lowerKey = key.toLowerCase();

            if (lowerKey === 'email' && typeof data[key] === 'string') {
                masked[key] = maskEmail(data[key]);
            } else if (
                (lowerKey === 'phone' || lowerKey === 'phonenumber' || lowerKey === 'mobile') &&
                typeof data[key] === 'string'
            ) {
                masked[key] = maskPhoneNumber(data[key]);
            } else if (
                (lowerKey === 'creditcard' || lowerKey === 'creditcardnumber' || lowerKey === 'cardnumber') &&
                typeof data[key] === 'string'
            ) {
                masked[key] = maskCreditCard(data[key]);
            } else {
                masked[key] = maskSensitiveData(data[key]);
            }
        }
        return masked;
    }
    return data;
}

function maskEmail(email: string): string {
    // Example: 'joedoe@gmail.com' -> 'jo***@gmail.com'
    const atIndex = email.indexOf('@');
    if (atIndex < 2) return '***' + email.substring(atIndex);
    return email.substring(0, 2) + '***' + email.substring(atIndex);
}

function maskPhoneNumber(phone: string): string {
    // Mask all but last 2 digits, keep + if present
    // e.g. '+1234567890' -> '+********90'
    const digits = phone.replace(/\D/g, '');
    if (digits.length < 2) return '*'.repeat(phone.length);
    const maskedLen = digits.length - 2;
    let masked = '';
    let digitIdx = 0;
    for (let i = 0; i < phone.length; i++) {
        if (/\d/.test(phone[i])) {
            if (digitIdx < maskedLen) {
                masked += '*';
            } else {
                masked += phone[i];
            }
            digitIdx++;
        } else {
            masked += phone[i];
        }
    }
    return masked;
}

function maskCreditCard(card: string): string {
    // Mask all but last 4 digits: '4111 2222 3333 4444' -> '**** **** **** 4444'
    return card.replace(/\d(?=\d{4})/g, '*');
}

// Middleware to mask sensitive fields in all GET responses
app.use((req, res, next) => {
    if (req.method !== 'GET') return next();

    const originalJson = res.json.bind(res);
    res.json = (body: any) => {
        const maskedBody = maskSensitiveData(body);
        return originalJson(maskedBody);
    };
    next();
});

