// --- A/B Testing Support ---

type ExperimentVariant = string;

interface Experiment {
    name: string;
    variants: ExperimentVariant[];
}

const experiments: Experiment[] = [
    {
        name: 'landing_page_redesign',
        variants: ['A', 'B'],
    },
    {
        name: 'checkout_button_color',
        variants: ['blue', 'green', 'red'],
    },
];

// Simple hash function for assignment
function hashString(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
        hash = ((hash << 5) - hash) + str.charCodeAt(i);
        hash |= 0;
    }
    return Math.abs(hash);
}

// Assign user to experiment variants based on IP hash
function assignExperiment(req: express.Request, res: express.Response, next: express.NextFunction) {
    const ip = req.ip || req.headers['x-forwarded-for'] as string || req.connection.remoteAddress || '';
    (req as any).experimentAssignments = {};
    for (const exp of experiments) {
        const hash = hashString(ip + exp.name);
        const variant = exp.variants[hash % exp.variants.length];
        (req as any).experimentAssignments[exp.name] = variant;
        res.setHeader(`X-Experiment-${exp.name}`, variant);
    }
    next();
}

// Helper to track experiment events
async function trackExperiment({
    experiment,
    variant,
    userId,
    event,
    meta = {},
}: {
    experiment: string,
    variant: string,
    userId?: string,
    event: string,
    meta?: Record<string, any>
}) {
    // You could save this in a DB table 'experiment_events'
    await db.insert('experiment_events', {
        experiment,
        variant,
        userId: userId || null,
        event,
        meta: JSON.stringify(meta),
        timestamp: new Date().toISOString(),
    });
}

