    const { name, email } = req.body;
    if ((req as any).dryRun) {
        // Basic validation
        if (!name || !email) {
            return res.status(400).json({ error: 'Missing required fields', dryRun: true });
        }
        // Would insert this user
        return res.json({
            dryRun: true,
            wouldAffect: {
                table: 'users',
                operation: 'insert',
                values: { name, email }
            }
        });
    }
    const result = await db.insert('users', { name, email });
