// Helper to check dependencies before deletion
async function checkDependencies(entity: 'user' | 'product', id: string) {
    if (entity === 'user') {
        // Check for orders with this userId
        const orders = await db.query('SELECT * FROM orders WHERE userId = ?', [id]);
        if (orders && orders.length > 0) {
            return {
                hasDependency: true,
                details: {
                    dependentType: 'orders',
                    dependentRecords: orders
                }
            };
        }
    } else if (entity === 'product') {
        // Check for orders whose items reference this product id
        // Assuming items is a JSON array of {productId, quantity,...}
        const orders = await db.query('SELECT * FROM orders');
        const dependentOrders = [];
        for (const order of orders) {
            let items = order.items;
            if (typeof items === 'string') {
                try {
                    items = JSON.parse(items);
                } catch {
                    items = [];
                }
            }
            if (Array.isArray(items) && items.some((item: any) => String(item.productId) === String(id))) {
                dependentOrders.push(order);
            }
        }
        if (dependentOrders.length > 0) {
            return {
                hasDependency: true,
                details: {
                    dependentType: 'orders',
                    dependentRecords: dependentOrders
                }
            };
        }
    }
    return { hasDependency: false };
}

