// Helper function for exponential backoff
function sleep(ms: number) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// Helper to check if an error is transient (connection timeout, deadlock)
function isTransientError(error: any): boolean {
    if (!error) return false;
    const msg = typeof error.message === 'string' ? error.message.toLowerCase() : '';
    if (msg.includes('timeout') || msg.includes('deadlock')) return true;
    // MySQL error codes: 1205 = Lock wait timeout exceeded; 1213 = Deadlock found
    if (typeof error.code === 'string' && (error.code === 'PROTOCOL_SEQUENCE_TIMEOUT' || error.code === 'ETIMEDOUT')) return true;
    if (typeof error.errno === 'number' && (error.errno === 1205 || error.errno === 1213)) return true;
    return false;
}

async function withRetry<T>(fn: () => Promise<T>, operation: string = 'db.query'): Promise<T> {
    const maxRetries = 3;
    const backoffs = [100, 200, 400];
    let lastError: any;
    for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
            return await fn();
        } catch (err) {
            lastError = err;
            if (isTransientError(err) && attempt < maxRetries - 1) {
                console.warn(`[withRetry] Transient error on "${operation}", retrying attempt ${attempt + 1} in ${backoffs[attempt]}ms...`, err);
                await sleep(backoffs[attempt]);
                continue;
            } else {
                throw err;
            }
        }
    }
    throw lastError;
}

