import crypto from 'crypto';

const SIGNING_SECRET = process.env.SIGNING_SECRET || 'supersecretkey';

const app = express();
app.use(express.json());

// signResponse middleware
function signResponse(req: express.Request, res: express.Response, next: express.NextFunction) {
    const oldJson = res.json;
    res.json = function (body: any) {
        let payload: string;
        try {
            payload = JSON.stringify(body);
        } catch {
            payload = '';
        }
        const signature = crypto.createHmac('sha256', SIGNING_SECRET).update(payload).digest('hex');
        res.setHeader('X-Response-Signature', signature);
        return oldJson.call(this, body);
    };
    next();
}

