// Middleware: IP Allowlist
function ipAllowlistMiddleware(req: express.Request, res: express.Response, next: express.NextFunction) {
    // Skip /health
    if (req.path === '/health') return next();
    const ip = req.ip || req.connection.remoteAddress || '';
    if (isIpAllowed(ip)) {
        return next();
    }
    res.status(403).json({ error: 'Forbidden: IP not in allowlist' });
}

