function parseHttpDate(date: string | undefined): number | null {
    if (!date) return null;
    const parsed = Date.parse(date);
    return isNaN(parsed) ? null : parsed;
}

async function checkPrecondition(
    table: string,
    id: string,
    req: express.Request,
    res: express.Response
): Promise<{ passed: boolean, record?: any }> {
    const recordArr = await db.query(`SELECT * FROM ${table} WHERE id = ?`, [id]);
    const record = Array.isArray(recordArr) ? recordArr[0] : recordArr;
    if (!record) {
        res.status(404).json({ error: `${table.slice(0, -1)[0].toUpperCase() + table.slice(1, -1).slice(1)} not found` });
        return { passed: false };
    }
    const ifUnmodifiedSince = req.header('If-Unmodified-Since');
    if (ifUnmodifiedSince) {
        const headerTime = parseHttpDate(ifUnmodifiedSince);
        const updatedAt = record.updated_at ? Date.parse(record.updated_at) : null;
        if (headerTime === null || updatedAt === null) {
            res.status(400).json({ error: 'Invalid If-Unmodified-Since or record missing updated_at' });
            return { passed: false };
        }
        if (updatedAt > headerTime) {
            res.status(412).json({ error: 'Resource was modified', updated_at: record.updated_at });
            return { passed: false };
        }
    }
    return { passed: true, record };
}

