// Query logging buffer and wrapper
type QueryLogEntry = {
    method: string;
    query: string;
    params: any[] | object | undefined;
    durationMs: number;
    resultCount: number;
    timestamp: number;
};

const QUERY_LOG_BUFFER_SIZE = 100;
const queryLogBuffer: QueryLogEntry[] = new Array(QUERY_LOG_BUFFER_SIZE);
let queryLogIndex = 0;
let queryLogCount = 0;

function logQuery(entry: QueryLogEntry) {
    queryLogBuffer[queryLogIndex] = entry;
    queryLogIndex = (queryLogIndex + 1) % QUERY_LOG_BUFFER_SIZE;
    if (queryLogCount < QUERY_LOG_BUFFER_SIZE) {
        queryLogCount++;
    }
}

async function queryLogger<T>(
    method: 'query' | 'insert' | 'update' | 'delete',
    fn: (...args: any[]) => Promise<T>,
    query: string,
    params?: any
): Promise<T> {
    const start = process.hrtime();
    let result: any;
    let resultCount = 0;
    try {
        result = await fn(query, params);
        if (Array.isArray(result)) {
            resultCount = result.length;
        } else if (typeof result === 'object' && result !== null) {
            if ('length' in result && typeof result.length === 'number') {
                resultCount = result.length;
            } else if ('affectedRows' in result) {
                resultCount = result.affectedRows;
            } else if ('id' in result) {
                resultCount = 1;
            } else {
                resultCount = 1;
            }
        } else {
            resultCount = result ? 1 : 0;
        }
        return result;
    } finally {
        const diff = process.hrtime(start);
        const durationMs = diff[0] * 1000 + diff[1] / 1e6;
        logQuery({
            method,
            query,
            params,
            durationMs,
            resultCount,
            timestamp: Date.now(),
        });
    }
}

