// In-memory cache and hit/miss stats
type CacheKey = 'products' | 'activeUserCount' | 'recentOrdersSummary';

interface CacheStats {
    hits: number;
    misses: number;
}

const cache: Record<CacheKey, any> = {
    products: null,
    activeUserCount: null,
    recentOrdersSummary: null,
};

const cacheStats: Record<CacheKey, CacheStats> = {
    products: { hits: 0, misses: 0 },
    activeUserCount: { hits: 0, misses: 0 },
    recentOrdersSummary: { hits: 0, misses: 0 },
};

// Cache access helpers
async function getCached<T>(key: CacheKey, loader: () => Promise<T>): Promise<T> {
    if (cache[key] !== null) {
        cacheStats[key].hits++;
        return cache[key];
    } else {
        cacheStats[key].misses++;
        const data = await loader();
        cache[key] = data;
        return data;
    }
}

// Cache warmup function
async function warmupCache() {
    try {
        const [products, activeUserCount, recentOrdersSummary] = await Promise.all([
            db.query('SELECT * FROM products'),
            db.query('SELECT COUNT(*) as count FROM users WHERE active = 1').then((rows: any[]) => rows[0]?.count ?? 0),
            db.query('SELECT id, userId, total, status, createdAt FROM orders ORDER BY createdAt DESC LIMIT 10'),
        ]);
        cache.products = products;
        cache.activeUserCount = activeUserCount;
        cache.recentOrdersSummary = recentOrdersSummary;
        // Reset cache stats on warmup (optional)
        // Object.keys(cacheStats).forEach(key => {
        //     cacheStats[key as CacheKey] = { hits: 0, misses: 0 };
        // });
        console.log('Cache warmed up at', new Date().toISOString());
    } catch (err) {
        console.error('Cache warmup failed:', err);
    }
}

