// Active user count
app.get('/users/active/count', async (req, res) => {
    const count = await getCached(
        'activeUserCount',
        async () => db.query('SELECT COUNT(*) as count FROM users WHERE active = 1').then((rows: any[]) => rows[0]?.count ?? 0)
    );
    res.json({ activeUserCount: count });
});

// Recent orders summary
app.get('/orders/recent/summary', async (req, res) => {
    const summary = await getCached(
        'recentOrdersSummary',
        async () => db.query('SELECT id, userId, total, status, createdAt FROM orders ORDER BY createdAt DESC LIMIT 10')
    );
    res.json(summary);
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    // Warm cache on startup
    warmupCache();
    // Refresh cache every 5 minutes
    setInterval(warmupCache, 5 * 60 * 1000);
});

export default app;
